#!/usr/bin/env python3
"""AxionHost Panel — self-extracting setup. Run: python3 panel_setup.py  (creates all files in the current folder)"""
import base64, os, stat
F = {
'README-PANEL.md': '',
'app.py': '',
'config.panel.example.json': '',
'core.py': '',
'install-panel.sh': '',
'ops.py': '',
'panel_bot.py': '',
'plans.seed.json': '',
'requirements-panel.txt': 'Zmxhc2s+PTMuMApyZXF1ZXN0cz49Mi4zMQppdHNkYW5nZXJvdXM+PTIuMQpjcnlwdG9ncmFwaHk+PTQyCndhaXRyZXNzPj0zLjAKZGlzY29yZC5weT49Mi4zCg==',
'static/admin.js': '',
'static/fonts/Inter-Bold.woff': '',
'static/fonts/Inter-ExtraBold.woff': '',
'static/fonts/Inter-Medium.woff': '',
'static/fonts/Inter-Regular.woff': '',
'static/fonts/Inter-SemiBold.woff': '',
'static/home.css': '',
'static/logo.svg': '',
'static/panel.css': '',
'static/panel.js': '',
'templates/404.html': '',
'templates/admin.html': '',
'templates/base.html': '',
'templates/billing.html': '',
'templates/dashboard.html': '',
'templates/deploy.html': '',
'templates/earn.html': '',
'templates/home.html': '',
'templates/login.html': '',
'templates/maintenance.html': '',
'templates/server.html': '',
'templates/settings.html': '',
'worker.py': '',
}
for n, b in F.items():
    d = os.path.dirname(n)
    if d: os.makedirs(d, exist_ok=True)
    open(n, "wb").write(base64.b64decode(b))
    if n.endswith(".sh"): os.chmod(n, 0o755)
print("AxionHost Panel: %d files created.  Next: sudo ./install-panel.sh" % len(F))
